package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamEthicsBank2 {
  private const val T = "බෞද්ධ සදාචාරය, ගිහි විනය හා සමාජ දර්ශනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("නූතන සමාජයේ විවිධ ජාතීන් හා ආගමිකයන් අතර සහජීවනය ඇති කිරීමට ඉතාමත් යෝග්‍ය බෞද්ධ ප්‍රතිපත්තිය කුමක්ද?", "සතර සංග්‍රහ වස්තු හා මෛත්‍රී කරුණා පැතිරවීම", "තම මතය පමණක් බලෙන් පැටවීම", "අන්‍ය ආගම්වලට නිග්‍රහ කිරීම", "සමාජයෙන් හුදෙකලා වීම", "සමානාත්මතාව හා ප්‍රියවචනය ආගමික සංහිඳියාවට මඟ පාදයි."),
    q("අශෝක අධිරාජ්‍යයාගේ සෙල්ලිපිවලින් පවා ප්‍රකට කෙරුණු 'අන්‍ය ආගම්වලට ගරු කිරීමේ' බෞද්ධ පිළිවෙත කුමක්ද?", "සියලු ආගම්වල හරය හා යහපත් දේ අගය කර සමගිය රැකීම", "අනෙක් ආගම් තහනම් කිරීම", "පන්සල් පමණක් ගොඩනැගීම", "විවාද කරමින් කාලය ගත කිරීම", "අන්‍ය මත ඉවසීම හා ගරු කිරීම බුදුරදුන් දෙසූ ආදර්ශයකි."),
    q("දේවත්වයෙන් හෝ රජුන්ගෙන් ලැබෙන බලයට වඩා ධර්මය ශ්‍රේෂ්ඨ බව දක්වන බෞද්ධ සංකල්පය කුමක්ද?", "ධම්මාධිපතෙය්‍යය", "අත්තාධිපතෙය්‍යය", "ලෝකාධිපතෙය්‍යය", "රාජාධිපතෙය්‍යය", "ධර්මය හා සත්‍යය අධිපති කොට ගෙන තීරණ ගැනීම ධම්මාධිපතෙය්‍ය නම් වේ."),
    q("තම හෘදය සාක්ෂියට හා ආත්ම ගෞරවයට අනුව වැරදිවලින් වැළකී සිටීම හඳුන්වන්නේ කුමන ආධිපත්‍යය ලෙසද?", "අත්තාධිපතෙය්‍යය", "ලෝකාධිපතෙය්‍යය", "ධම්මාධිපතෙය්‍යය", "ධනාධිපතෙය්‍යය", "තමා කෙරෙහි ගෞරවයෙන් පාපයෙන් වැළකීම අත්තාධිපතෙය්‍යයයි."),
    q("ලෝකයේ නුවණැති ජනතාවගේ නින්දාවට පත් වේ යැයි සිතා වැරදිවලින් වැළකීම කුමන ආධිපත්‍යයද?", "ලෝකාධිපතෙය්‍යය", "අත්තාධිපතෙය්‍යය", "ධම්මාධිපතෙය්‍යය", "සේනාධිපතෙය්‍යය", "සමාජ වගකීම සලකා පවින් වැළකීම ලෝකාධිපතෙය්‍යයයි."),
    q("බෞද්ධ ආචාර විද්‍යාවට අනුව 'පුණ්‍ය ක්‍රියා වස්තු' දහය අතර මුලින්ම දැක්වෙන්නේ කුමක්ද?", "දාන", "සීල", "භාවනා", "අපචායන", "දාන, සීල, භාවනා, අපචායන, වෙය්‍යාවච්ච ආදී දස පුණ්‍ය ක්‍රියා වස්තු වේ."),
    q("දස පුණ්‍ය ක්‍රියා වස්තු අතර 'වෙය්‍යාවච්ච' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "වැඩිහිටියන්ට, ගිලනුන්ට හා පොදු කටයුතුවලට වත්පිළිවෙත් උපකාර කිරීම", "ධර්මය දේශනා කිරීම", "පින් අනුමෝදන් කිරීම", "දෘෂ්ටිය ඍජු කර ගැනීම", "කායිකව කරන උවටැන් හා සමාජ සේවා කටයුතු වෙය්‍යාවච්ච පුණ්‍ය ක්‍රියාවයි."),
    q("දස පුණ්‍ය ක්‍රියා අතර 'පත්තානුමෝදනා' යනු කුමක්ද?", "අන් අය කරන පින්කම් දැක සතුටු සිතින් අනුමෝදන් වීම", "තමා කළ පින් අනුන්ට දීම", "බණ ඇසීම", "සිල් රැකීම", "ඊර්ෂ්‍යාවෙන් තොරව අන් අයගේ පින් දැක සාධුකාර දී සතුටු වීම පත්තානුමෝදනාවයි."),
    q("දස පුණ්‍ය ක්‍රියා වස්තුවල අවසාන කරුණ වන 'දිට්ඨිජුකම්ම' යනු කුමක්ද?", "කර්මඵල පිළිබඳ නිවැරදි දැක්ම ඇති කර ගැනීම", "අලුත් ගොඩනැගිලි ඉදි කිරීම", "මල් පහන් පිදීම", "සත්‍ය වචන කීම", "කුසලාකුසල කර්ම හා පරලොව පිළිබඳ දැක්ම ඍජු කර ගැනීම දිට්ඨිජුකම්මයයි."),
    q("ගිහියෙකු විසින් රැකිය යුතු උසස්ම ශීලයක් ලෙස 'ආජීව අට්ඨමක ශීලයේ' සිල්පද ගණන කීයද?", "අටකි", "පහකි", "දහයකි", "හතකි", "කාය දුශ්චරිත 3, වචී දුශ්චරිත 4 හා මිච්ඡා ආජීවයෙන් වැළකීම යන 8 ආජීව අට්ඨමක ශීලයයි."),
    q("බුදුරදුන් දෙසූ 'පුද්ගල පවිත්‍රතාව' අනුව භෞතික වතුරෙන් හෝ ගිනි පූජාවෙන් පව් සේදිය නොහැකි බව දෙසුවේ කාටද?", "සුන්දරික භාරද්වාජ බමුණාට", "අනේපිඬු සිටුතුමාට", "බිම්බිසාර රජුට", "සිඟාල කුමරුට", "බාහුකා ආදී ගංගාවලින් පව් නොසේදෙන බවත් ශීලයෙන් හා මෛත්‍රියෙන් පිරිසිදු වන බවත් වදාළහ."),
    q("නාගරික හා ග්‍රාමීය සමාජයක සාමකාමී පැවැත්මට අත්‍යවශ්‍ය වන 'නොසැලකිලිමත් ලෙස මත්ද්‍රව්‍ය භාවිතයේ' ආදීනව හය දැක්වෙන සූත්‍රය කුමක්ද?", "සිඟාලෝවාද සූත්‍රය", "මහාමංගල සූත්‍රය", "වසල සූත්‍රය", "කරණීයමෙත්ත සූත්‍රය", "ධන හානිය, කලහ වැඩීම, රෝග හටගැනීම, අපකීර්තිය, ලැජ්ජා බිය නැතිවීම, නුවණ දුබල වීම සයයි."),
    q("බෞද්ධ සදාචාරයට අනුව 'ප්‍රියවචන' කතා කිරීම යනු කුමක්ද?", "සත්‍ය වූ, මෘදු වූ, ප්‍රියමනාප හා අර්ථවත් වචන කතා කිරීම", "අනුන් රවටන මුසාවාද කීම", "හිස් දෙඩවිලිවල යෙදීම", "තමා වර්ණනා කර ගැනීම", "දැඩි හෝ පරුෂ නොවී ආදරණීය ගෞරවනීය බසින් ඇමතීමයි."),
    q("ගිහි බෞද්ධ පවුලක සමගිය රැක ගැනීමට දරුවන් තුළ වර්ධනය කළ යුතු ප්‍රධාන ගුණාංගයක් කුමක්ද?", "කීකරු බව හා මව්පිය උපස්ථානය", "තමා කැමති සේ අනාරක්ෂිතව හැසිරීම", "වැඩිහිටියන් විවේචනය කිරීම", "ධනය නාස්ති කිරීම", "මව්පිය ගෞරවය පවුලේ සතුටට හා සමාජ සුරක්ෂිතතාවට පදනමයි."),
    q("සාමකාමී සමාජයක් ගොඩනැගීමට අත්‍යවශ්‍ය වන 'සමගි සම්පන්න බව' වෙනුවෙන් බුදුරදුන් උපමා කළ කතාව කුමක්ද?", "වට්ටක ජාතකය හෙවත් සමගි වටු කුරුල්ලන්ගේ කතාව", "වෙස්සන්තර ජාතකය", "චුල්ලපදුම ජාතකය", "මහාසීලව ජාතකය", "එකමුතු වූ කල දැලත් ඔසවාගෙන ඉගිලුණු වටු කුරුල්ලන් අසමගි වූ විට විනාශ විය."),
    q("ගැටුමක් හටගත් විට එය සමථයකට පත් කිරීම සඳහා බෞද්ධ සමාජයේ භාවිත කරන ක්‍රමවේදය කුමක්ද?", "සාකච්ඡාව, ඉවසීම හා අධිකරණ සමථ ක්‍රම", "පළිගැනීම", "බලහත්කාරය යෙදවීම", "හිංසනය පැතිරවීම", "විනය පිටකයේ සත්ත අධිකරණ සමථ ධර්ම මගින් සාමකාමී විසඳුම් දක්වා ඇත."),
    q("විනිවිද භාවයෙන් හා මධ්‍යස්ථව සාකච්ඡා කර පොදු එකඟතාවයෙන් තීරණ ගැනීමේ බෞද්ධ සංඝ ක්‍රමය කුමක්ද?", "සංඝ කර්ම හා යෙභුය්‍යසිකා ක්‍රමය", "රාජ ආඥාව", "තනි පුද්ගල ආධිපත්‍යය", "ගුප්ත තීරණ", "ප්‍රජාතන්ත්‍රවාදී ඡන්ද විමසීම හා සභා සම්මුතිය බුදු සසුනේ මුල සිටම පැවතුණි."),
    q("පාලකයෙකු රටවැසියන්ට පියෙකු සේ සැලකිය යුතු බව දක්වන බෞද්ධ ඉගැන්වීම කුමක්ද?", "පිය-පුතු සම්බන්ධතාව (පුත්තං විය මාමකං)", "ස්වාමි-දාස සම්බන්ධතාව", "සතුරු ආකල්පය", "බදු අය කරන්නාගේ ආකල්පය", "පාලකයා ජනතාවගේ දුකේදී පිහිට වන ආරක්ෂකයා විය යුතුය."),
    q("සදාචාර සම්පන්න ගිහි දිවියක් ගෙවීම සඳහා වැළකිය යුතු අපරාධ හෙවත් කර්ම ක්ලේශ සතර කුමන සූත්‍රයේ එයිද?", "සිඟාලෝවාද සූත්‍රයේ", "ආනාපානසති සූත්‍රයේ", "සච්චවිභංග සූත්‍රයේ", "අනත්තලක්ඛණ සූත්‍රයේ", "ප්‍රාණඝාත, අදත්තාදාන, කාමමිථ්‍යාචාර, මුසාවාද යන සතර සිඟාලෝවාද සූත්‍රයේ විස්තර වේ."),
    q("මනුෂ්‍යයන් තුළ සමානාත්මතාව තහවුරු කිරීමට බුදු සසුන තුළ ක්‍රියාත්මක කළ විශේෂිත ක්‍රියාමාර්ගය කුමක්ද?", "සියලු කුලවල ජනතාවට පැවිද්ද හා නිවන් මඟ විවෘත කිරීම", "එක් කුලයකට පමණක් බණ දෙසීම", "වෙනම විහාර ඉදි කිරීම", "සේවකයන් බැහැර කිරීම", "සිව් මහා ගංගා මුහුදට වැටුණු පසු නම් ගොත් නැති වන්නා සේ සසුන තුළ සියල්ලෝ සමාන වෙති."),
    q("සිව් මහා ගංගා මහා සාගරයට වැටුණු පසු පෙර නම් අත්හැර 'මහා සමුද්‍රය' යන නම ගන්නා සේ සිව් කුලයේ පැවිද්දන් හඳුන්වන්නේ කෙසේද?", "ශ්‍රමණ ශාක්‍යපුත්‍රීයයන් ලෙස", "බ්‍රාහ්මණයන් ලෙස", "ක්ෂත්‍රියන් ලෙස", "වෛශ්‍යයන් ලෙස", "පහාරාද සූත්‍රයේදී සාගරයේ ආශ්චර්යමත් ගුණ අතර මෙය උපමා කර ඇත."),
    q("පහාරාද අසුරේන්ද්‍රයාට බුදුරදුන් දෙසූ පහාරාද සූත්‍රයේ මහා සාගරයට උපමා කළේ කුමක්ද?", "බුද්ධ ශාසනය හෙවත් ධර්ම විනය", "රජ මාලිගාව", "දිව්‍ය ලෝකය", "වෙළඳ නගරය", "සාගරයේ ආශ්චර්ය අට හා සමාන ගුණ අටක් බුද්ධ ශාසනයේ ඇති බව පෙන්වූහ."),
    q("සත්ව හිංසනය හා සත්ව ඝාතනය පිටුදකින බෞද්ධ සමාජයේ වැදගත්ම චාරිත්‍රයක් කුමක්ද?", "අභය දානය ලබා දීම හා නිර්මාංශ ආහාර අගය කිරීම", "සත්ව බිලි පූජා පැවැත්වීම", "දඩයමේ යෑම", "සතුන් සිරකර තැබීම", "ප්‍රාණඝාතයෙන් වැළකී සියලු සතුන්ට කරුණාව දැක්වීම බෞද්ධ පිළිවෙතයි."),
    q("නිවැරදි සමාජ නායකයෙකු තුළ නොතිබිය යුතු පාලන දුර්වලතාවයක් කුමක්ද?", "අගතිගාමී බව හා ඒකාධිපති බව", "ඉවසීම", "විනිවිද භාවය", "සාධාරණත්වය", "නායකයා කිසි විටෙකත් ඡන්ද, දෝස, භය, මෝහ යන අගතිවලට යටත් නොවිය යුතුය."),
    q("රටක සාමය හා සුරක්ෂිතතාව බිඳ වැටීමට ප්‍රධාන හේතුවක් වන්නේ 'සොරකම හා දරිද්‍රතාව' බව පැවසෙන සූත්‍රය කුමක්ද?", "කූටදන්ත සූත්‍රය", "ආලවක සූත්‍රය", "ධම්මචක්ක සූත්‍රය", "බොජ්ඣංග සූත්‍රය", "දඬුවම් දීමෙන් පමණක් සොරකම නැවැත්විය නොහැකි අතර ජනතාවට රැකියා හා ප්‍රාග්ධනය දිය යුතු බව දැක්වේ."),
    q("කූටදන්ත සූත්‍රයට අනුව රටක අපරාධ මැඩපැවැත්වීමට පාලකයා ගත යුතු නිවැරදි පියවර කුමක්ද?", "ගොවීන්ට බීජ හා වෙළඳුන්ට ප්‍රාග්ධනය ලබා දී රැකියා සැපයීම", "සියලු සොරුන් මරා දැමීම", "බදු බර වැඩි කිරීම", "වෙළඳාම තහනම් කිරීම", "ආර්ථික සුරක්ෂිතතාව ඇති කළ විට අපරාධ ස්වයංක්‍රීයව අඩු වන බව පෙන්වයි."),
    q("විවාදවලින් තොරව කණ්ඩායමක් සමගිව ක්‍රියා කිරීමට ඉවහල් වන 'චතුබ්බිධ සාමග්‍රියේ' ප්‍රධාන ලක්ෂණය කුමක්ද?", "පොදු අරමුණක් වෙනුවෙන් එකමුතුව කටයුතු කිරීම", "වෙනම කණ්ඩායම් සෑදීම", "අනුන්ගේ අඩුපාඩු විවේචනය", "නිහඬව කාලය ගෙවීම", "දැහැමි සමගිය සමාජ සංවර්ධනයට අත්‍යවශ්‍ය වේ."),
    q("වැඩිහිටි නිවාසවල දෙමාපියන් තනි නොකර නිවසේ රැකබලා ගැනීමට බලපාන බෞද්ධ සමාජ ධර්මය කුමක්ද?", "මාතාපිතු උපට්ඨානය (මව්පිය උපස්ථානය)", "අපරිග්‍රහය", "බ්‍රහ්මදණ්ඩය", "උපෝසථ ශීලය", "මහා මංගල සූත්‍රයේ මාතාපිතු උපට්ඨානය උතුම් මංගල කරුණක් ලෙස දක්වා ඇත."),
    q("පාසල් ශිෂ්‍යයෙකු සතු විය යුතු උසස් සදාචාර ලක්ෂණයක් වන 'ගුරු ගෞරවය' වඩාත් පැහැදිලි වන්නේ කෙසේද?", "අවවාද අනුශාසනා සකසා අසා ක්‍රියාත්මක කිරීමෙන්", "විභාග ප්‍රශ්න පමණක් මතක තබා ගැනීමෙන්", "පාසලට නොපැමිණීමෙන්", "මිතුරන් සමඟ විවාද කිරීමෙන්", "සක්කච්චං සිප්පපටිග්ගහණ (ගෞරවයෙන් ශිල්ප ඉගෙනීම) ශිෂ්‍ය යුතුකමකි."),
    q("දැහැමි සමාජයක සේවා යෝජකයා හා සේවකයා අතර තිබිය යුතු සම්බන්ධතාවය කවරාකාරද?", "අන්‍යෝන්‍ය ගෞරවය, සාධාරණ වැටුප් හා අවංක සේවය", "වහල් සේවය", "වැටුප් රහිත වැඩ", "වර්ජන හා කලහ පමණක්", "සේවක අයිතිවාසිකම් හා වගකීම් දෙපාර්ශවයම රැකිය යුතු බව බුදුදහම පෙන්වයි."),
    q("බෞද්ධ ගිහියෙකු සතු 'චාග' ගුණයෙන් ප්‍රකාශ වන්නේ කුමක්ද?", "මසුරුකම දුරු කර අත්හැරීමේ හා දන් දීමේ ස්වභාවය", "ධනය සඟවා තබා ගැනීම", "සොරකම් කිරීම", "තමා පමණක් පරිභෝජනය", "පරිත්‍යාගශීලී ජීවිතය පුද්ගලයාගේ මානසික සතුට හා සමාජ සුබසෙත වඩයි."),
    q("ගිහි බෞද්ධ සමාජයේ විවාහක යුවළක් සාර්ථක පවුල් දිවියක් ගත කිරීමට වැළකිය යුතු ප්‍රධාන වරද කුමක්ද?", "පරදාර සේවනය හා අවිශ්වාසය", "එකට පින්කම් කිරීම", "සාකච්ඡා කිරීම", "දෙමාපියන්ට සැලකීම", "අඹුසැමි විශ්වාසය බිඳීම පවුලේ හා සමාජයේ පිරිහීමට හේතු වේ."),
    q("මනුෂ්‍යයෙකු සතු 'සච්චවාදී' බව හෙවත් සත්‍යවාදී බව සමාජයට වැදගත් වන්නේ ඇයි?", "පුද්ගල විශ්වසනීයත්වය හා යුක්තිය තහවුරු වන බැවින්", "කෙටි කාලීන ලාභ ලැබෙන බැවින්", "අනුන් බිය ගැන්විය හැකි බැවින්", "කතා නොකර සිටිය හැකි බැවින්", "සත්‍යය රැකීම නීතිගරුක සමාජයක පදනමයි."),
    q("තරුණ වියේදී අනාගත අභිවෘද්ධිය වෙනුවෙන් වැළකිය යුතු පුරුද්දක් ලෙස 'සමජ්ජාභිචරණය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "නිෂ්ඵල උත්සව හා සැණකෙළි පසුපස යමින් කාලය නාස්ති කිරීම", "උදෑසන පාසල් යාම", "ක්‍රීඩා පුහුණුව", "පුස්තකාල භාවිතය", "වගකීම් පැහැර හැර විනෝදාස්වාදයට ලොල් වීම ධනය හා කාලය නසයි."),
    q("ගිහි පුද්ගලයෙකු තම පවුලට හා සමාජයට ඉටු කළ යුතු කාර්යයන් නිසි කලට නොපිරිහෙළා ඉටු කිරීම කවර ගුණයක්ද?", "අප්‍රමාදය හා කාර්යශූරත්වය", "කුසීතකම", "අකෘතඥතාව", "උද්ධච්චය", "අලස නොවී වගකීම් ඉටු කිරීම මෙලොව පරලොව දියුණුවේ රහසයි."),
    q("රාජ්‍ය පාලකයෙකු ජනතාවගේ ප්‍රසාදය දිනා ගැනීමට නම් රටේ පැවතිය යුතු ප්‍රධාන ලක්ෂණය කුමක්ද?", "ධාර්මික පාලනය හා ආර්ථික ස්ථාවරත්වය", "දැඩි හමුදා පාලනය", "භීෂණය", "මිථ්‍යා විශ්වාස පැතිරවීම", "'රාජානෝ ධම්මිකා හොන්තු' යනුවෙන් දැහැමි පාලනය නිරතුරුව අගය කෙරේ."),
    q("බෞද්ධ සමාජ දර්ශනයේ 'පුද්ගල නිදහස' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "වගකීම් සහිතව විමර්ශනය කර යහපත් දේ තෝරා ගැනීමේ නිදහස", "ඕනෑම අපරාධයක් කිරීමේ නිදහස", "සමාජ නීති කඩ කිරීමේ නිදහස", "අනුන්ට හිංසා කිරීමේ නිදහස", "කාලාම සූත්‍රයෙන් චින්තන නිදහසත් පංච ශීලයෙන් සමාජ වගකීමත් දැක්වේ."),
    q("මහජන සේවයේ නියුතු නිලධාරියෙකු තුළ අනිවාර්යයෙන්ම පැවතිය යුතු බෞද්ධ ගුණාංගයක් කුමක්ද?", "අගති විරහිත බව හා අල්ලස් දූෂණයෙන් වැළකීම", "හිතවතුන්ට පමණක් උදව් කිරීම", "සේවාලාභීන් රස්තියාදු කිරීම", "අතිරේක මුදල් අය කිරීම", "සතර අගතියෙන් තොරව නිවැරදි සේවයක් සැලසීම යහපාලනයයි."),
    q("වයස්ගත වූ පසු දෙමාපියන්ට සලකන දරුවන් 'දෙව්ලොවට පාර කපා ගන්නා බව' දැක්වෙන්නේ කුමන බුදු වදනින්ද?", "බ්‍රහ්මාති මාතාපිතරෝ (මව්පියෝ බ්‍රහ්මයෝ වෙති)", "අනිච්චා වත සංඛාරා", "නිබ්බාණං පරමං සුඛං", "සබ්බේ සංඛාරා අනත්තා", "මව්පියන් සතර බ්‍රහ්ම විහරණයෙන් දරුවන් රකින බැවින් ඔවුන්ට පිදිය යුතුය."),
    q("බෞද්ධ ආචාර විද්‍යාවට අනුව 'පව්' සහ 'පින්' වෙන් කර හඳුනා ගන්නා මූලික මිනුම් දණ්ඩ කුමක්ද?", "ක්‍රියාවකින් තමාට හා අනුන්ට යහපතක් සිදුවේද නැතහොත් හානියක් සිදුවේද යන්න", "වැය වන මුදල් ප්‍රමාණය", "ප්‍රසිද්ධිය", "සමාජ තත්ත්වය", "කුසල් යනු යහපත් විපාක ගෙන දෙන හා කෙලෙස් අඩු කරන ක්‍රියා වේ."),
    q("විවාදයකදී හෝ කතාබහකදී අනෙකාගේ මතයට සාවධානව ඇහුම්කන් දීම කවර ගුණාංගයක්ද?", "ඉවසීම (ඛන්ති) හා විනයගරුක සන්නිවේදනය", "ආත්මාර්ථකාමී බව", "මානය", "උද්ධච්චය", "සවන් දීම හා ගරු කිරීම සාමකාමී සංවාදයක ලක්ෂණයකි."),
    q("බෞද්ධ සමාජයේ සමගි බව විනාශ කරන ප්‍රධාන සමාජ පිළිලයක් ලෙස හඳුන්වන්නේ කුමක්ද?", "ඊර්ෂ්‍යාව හා මසුරුකම", "මුදිතාව", "දානය", "කරුණාව", "ඊර්ෂ්‍යාව නිසා අනුන්ගේ දියුණුව නොඉවසන අතර සමාජ ගැටුම් හටගනී."),
    q("අසල්වැසියන් සමඟ සුහදව ජීවත් වීම සඳහා වැදගත් වන බෞද්ධ සමාජ ප්‍රතිපදාව කුමක්ද?", "අසල්වැසියන්ගේ සැප දුක බෙදා ගැනීම හා හානි නොකිරීම", "අසල්වැසි ඉඩම් අල්ලා ගැනීම", "ශබ්ද දූෂණය කිරීම", "කතා නොකර සිටීම", "මෛත්‍රිය හා සතර සංග්‍රහ වස්තු අසල්වැසි සබඳතා ශක්තිමත් කරයි."),
    q("ගිහි බෞද්ධයන් විසින් සමාජ සේවා කටයුතුවල යෙදීමේදී තිබිය යුතු නිවැරදි ආකල්පය කුමක්ද?", "ප්‍රතිලාභ හෝ කීර්තිය නොතකා කරුණාවෙන් උපකාර කිරීම", "පුවත්පත්වල නම පළ කර ගැනීමට කිරීම", "දේශපාලන වාසි බලාගෙන කිරීම", "අනුන්ට ණය ගැති කිරීමට කිරීම", "නිහතමානී සේවාව උසස් පුණ්‍ය කර්මයකි."),
    q("විද්‍යාත්මක හා තාක්ෂණික දියුණුවත් සමඟ ඇතිවන 'පරිභෝගිකවාදී ආශාවන්' පාලනය කර ගැනීමට උගන්වන බෞද්ධ ගුණය කුමක්ද?", "සන්තුට්ඨිතාව හා අල්පේච්ඡතාව", "තෘෂ්ණාව වැඩි කිරීම", "මසුරුකම", "ණය ගැනීම", "ලද දෙයින් සතුටු වීමෙන් අනවශ්‍ය තරගකාරිත්වයෙන් හා මානසික පීඩනයෙන් මිදිය හැක."),
    q("මත්ද්‍රව්‍ය, දුම්වැටි හා මත්පැන් වැනි දේ ප්‍රචාරය හා අලෙවිය බුදුදහම ප්‍රතික්ෂේප කරන්නේ කුමන ධර්මය යටතේද?", "පංච වණිජ්ජා හා පස්වන සිල්පදය යටතේ", "දස රාජ ධර්ම යටතේ", "සතර ඉර්දිපාද යටතේ", "සප්ත බොජ්ඣංග යටතේ", "මත්ද්‍රව්‍ය වෙළඳාම නොකළ යුතු අකැප වෙළඳාමක් ලෙස පනවා ඇත."),
    q("සමාජයක විවිධ වෘත්තීන් හා කර්මාන්ත සිදු කරන සියලු දෙනාට ගරු කළ යුතු බව බුදුරදුන් දෙසුවේ කුමක් අනුවද?", "දැහැමි කුමන වෘත්තියක් වුවද එය සමාජ පැවැත්මට දායක වන බැවින්", "උසස් කුලයේ අය පමණක් වැදගත් බැවින්", "ධනවත් වෙළඳුන් පමණක් ගරු කළ යුතු බැවින්", "ශ්‍රමිකයන් පහත් බැවින්", "ශ්‍රමයේ ගෞරවය බුදුදහමින් අගය කෙරේ."),
    q("වැඩිහිටි ගුරුවරුන් හා දෙමාපියන් කෙරෙහි කළගුණ දැක්වීම සමාජ සදාචාරය රැකීමට ඉවහල් වන බව පෙන්වන්නේ කුමන උපමාවෙන්ද?", "මිහිරි පල ලබා දෙන ගසක අතු බිඳ නොදැමීමේ උපමාවෙන්", "ගඟෙන් එතෙර වී ඔරුව විසි කිරීම", "ගින්නට පිදුරු දැමීම", "රන් තැටිය කිලිටි කිරීම", "උපකාර කළ අයට ද්‍රෝහී වීම මිත්‍රද්‍රෝහී පාපයක් බව ජාතක කතාවලින් පෙන්වයි."),
    q("විපතට පත් වූ සතුරෙකුට පවා අවශ්‍ය අවස්ථාවකදී පිහිට වීම බෞද්ධ සමාජයේ කුමන උසස් ගුණයද?", "මහා කරුණාව හා වෛර නොකිරීම", "දුර්වලකම", "බියගුලු බව", "රැවටිලිකාර බව", "වෛරයෙන් තොරව මනුෂ්‍යත්වයට ගරු කිරීම බෞද්ධ සාරධර්මයකි."),
    q("සාමකාමී පවුල් හා සමාජ සබඳතා ගොඩනගා ගැනීමේදී තරුණ පරපුර විසින් මුලින්ම දියුණු කරගත යුතු ගුණය කුමක්ද?", "ආත්ම සංයමය හා විනයගරුක බව", "උද්ධච්ච බව", "තරගකාරී කෝපය", "අවිනීත බව", "තම ආවේග පාලනය කර ගැනීම සමාජ සාමයේ මූලික පියවරයි."),
    q("ලෝකයේ සාමය ඇති කිරීමට බෞද්ධ සමාජය පළමුව කළ යුත්තේ කුමක්ද?", "තම සිත තුළ සාමය හා මෛත්‍රිය ඇති කර ගැනීම", "විශාල අවි ගබඩා තැනීම", "අනෙක් රටවල් පාලනය කිරීම", "වාද විවාද ඇති කිරීම", "අභ්‍යන්තර සාමය බාහිර සමාජ සාමයට පදනම වන බව බුදුදහම උගන්වයි.")
  )
}
